/**
 * Get matching packages for a specific place and region
 */
window.CH_getPackagesForPlace = function(place, regionKey) {
    if (!place) return [];
    var placeName = (place.name || '').toLowerCase().trim();
    var placeSlug = (place.slug || '').toLowerCase().trim();
    var region = (regionKey || place.region || '').toLowerCase().trim();

    // 1. Direct name/keyword match in packages
    var exactMatches = window.CH_PACKAGES.filter(function(pkg) {
        var kw = pkg.searchKeywords || '';
        var title = (pkg.title || '').toLowerCase();
        var route = (pkg.route || '').toLowerCase();
        return title.indexOf(placeName) !== -1 || 
               route.indexOf(placeName) !== -1 || 
               kw.indexOf(placeName) !== -1 ||
               (placeSlug && (title.indexOf(placeSlug) !== -1 || route.indexOf(placeSlug) !== -1));
    });

    if (exactMatches.length >= 3) {
        return exactMatches.slice(0, 6);
    }

    // 2. Add region-specific fallback packages
    var regionMap = {
        'darjeeling': ['darjeeling', 'sandakphu'],
        'kalimpong': ['kalimpong'],
        'sikkim': ['sikkim', 'silk-route', 'north-sikkim'],
        'dooars': ['dooars']
    };
    var allowedRegions = regionMap[region] || [region];

    var regionalPackages = window.CH_PACKAGES.filter(function(pkg) {
        return allowedRegions.indexOf(pkg.region) !== -1 && exactMatches.indexOf(pkg) === -1;
    });

    var combined = exactMatches.concat(regionalPackages);
    return combined.slice(0, 6);
};

/**
 * Get matching verified homestays / stays for a specific place and region
 */
window.CH_getStaysForPlace = function(place, regionKey) {
    if (!place) return [];
    var placeName = (place.name || '').toLowerCase().trim();
    var placeSlug = (place.slug || '').toLowerCase().trim();
    var region = (regionKey || place.region || '').toLowerCase().trim();
    var subRegion = (place.subRegion || '').toLowerCase().trim();

    // Clean common words like 'town', 'village', 'sightseeing'
    var searchToken = placeName.replace(/sightseeing|safari|town|village|west|east|north|south|&|activities/gi, '').trim();

    // 1. Direct name/distance match in hotels
    var exactMatches = window.CH_HOTELS.filter(function(h) {
        var hName = (h.name || '').toLowerCase();
        var hDist = (h.distance || '').toLowerCase();
        var hSub = (h.subRegion || '').toLowerCase();
        var hView = (h.view || '').toLowerCase();
        
        if (searchToken.length >= 3) {
            if (hName.indexOf(searchToken) !== -1 || hDist.indexOf(searchToken) !== -1 || hSub.indexOf(searchToken) !== -1) {
                return true;
            }
        }
        return hName.indexOf(placeName) !== -1 || hDist.indexOf(placeName) !== -1;
    });

    if (exactMatches.length >= 3) {
        return exactMatches.slice(0, 6);
    }

    // 2. Sub-region or region match
    var regionalMatches = window.CH_HOTELS.filter(function(h) {
        if (exactMatches.indexOf(h) !== -1) return false;
        var hReg = (h.region || '').toLowerCase();
        var hSub = (h.subRegion || '').toLowerCase();

        if (subRegion && (hSub.indexOf(subRegion) !== -1 || subRegion.indexOf(hSub) !== -1)) {
            return true;
        }

        if (region === 'darjeeling' && hReg === 'darjeeling') return true;
        if (region === 'kalimpong' && hReg === 'kalimpong') return true;
        if (region === 'sikkim' && hReg === 'sikkim') return true;
        return false;
    });

    var combined = exactMatches.concat(regionalMatches);

    // If Dooars or other area with no direct hotels in catalog, provide curated nearby options
    if (combined.length === 0) {
        // Fallback to top rated stays from catalog
        combined = window.CH_HOTELS.slice(0, 4);
    }

    return combined.slice(0, 6);
};
